class LifecycleEventChannelBase(ServiceBase):

    async def subscribe_lifecycle_events(
        self, lifecycle_event_filter: "LifecycleEventFilter"
    ) -> AsyncIterator[ActorLifecycleEvent]:
        raise grpclib.GRPCError(grpclib.const.Status.UNIMPLEMENTED)
        yield ActorLifecycleEvent()

    async def publish_lifecycle_event(
        self, actor_lifecycle_event: "ActorLifecycleEvent"
    ) -> "__common_v1__.Empty":
        raise grpclib.GRPCError(grpclib.const.Status.UNIMPLEMENTED)

    async def __rpc_subscribe_lifecycle_events(
        self, stream: "grpclib.server.Stream[LifecycleEventFilter, ActorLifecycleEvent]"
    ) -> None:
        request = await stream.recv_message()
        await self._call_rpc_handler_server_stream(
            self.subscribe_lifecycle_events,
            stream,
            request,
        )

    async def __rpc_publish_lifecycle_event(
        self, stream: "grpclib.server.Stream[ActorLifecycleEvent, __common_v1__.Empty]"
    ) -> None:
        request = await stream.recv_message()
        response = await self.publish_lifecycle_event(request)
        await stream.send_message(response)

    def __mapping__(self) -> Dict[str, grpclib.const.Handler]:
        return {
            "/plexspaces.actor.v1.LifecycleEventChannel/SubscribeLifecycleEvents": grpclib.const.Handler(
                self.__rpc_subscribe_lifecycle_events,
                grpclib.const.Cardinality.UNARY_STREAM,
                LifecycleEventFilter,
                ActorLifecycleEvent,
            ),
            "/plexspaces.actor.v1.LifecycleEventChannel/PublishLifecycleEvent": grpclib.const.Handler(
                self.__rpc_publish_lifecycle_event,
                grpclib.const.Cardinality.UNARY_UNARY,
                ActorLifecycleEvent,
                __common_v1__.Empty,
            ),
        }
